#include <stdio.h>
#include <string.h>
/*
 * ex10：系统调用号查表分发（syscalls[] 表）
 * Linux 内核里就有一个 sys_call_table：数组下标是调用号，元素是服务例程地址。
 * 用户态把「调用号 + 参数」放进寄存器，陷入内核后内核按下标取函数指针。
 * 本程序用一个小表还原这个分发过程，并演示「未知调用号」返回 -ENOSYS。
 */
typedef struct {
    const char *name;
    int nr;              /* 系统调用号（示例值，非真实编号） */
    const char *handler; /* 内核服务例程 */
    int nargs;
} Entry;

static Entry table[] = {
    {"read",    0,  "ksys_read",  3},
    {"write",   1,  "ksys_write", 3},
    {"openat",  257, "do_sys_openat2", 4},
    {"close",   3,  "ksys_close", 1},
    {"fork",    57, "kernel_clone", 0},
    {"execve",  59, "do_execve",  3}
};

static int lookup(const char *name) {
    for (int i = 0; i < (int)(sizeof(table) / sizeof(table[0])); i++)
        if (strcmp(table[i].name, name) == 0) return i;
    return -1;
}

int main(void) {
    const char *calls[] = {"write", "openat", "fork", "io_uring_setup"};
    int m = (int)(sizeof(calls) / sizeof(calls[0]));

    printf("%-16s %-8s %-18s %-6s %s\n", "调用名", "调用号", "服务例程", "参数", "分发结果");
    printf("--------------------------------------------------------------------------\n");
    for (int i = 0; i < m; i++) {
        int idx = lookup(calls[i]);
        if (idx < 0) {
            printf("%-16s %-8s %-18s %-6s %s\n", calls[i], "-", "-", "-", "返回 -ENOSYS(38)");
        } else {
            printf("%-16s %-8d %-18s %-6d %s\n", table[idx].name, table[idx].nr,
                   table[idx].handler, table[idx].nargs, "按号取址 -> 进服务例程");
        }
    }
    printf("\n表大小 = %d 项（真实 Linux x86-64 上有 500+ 项，见 include/linux/syscalls.h）\n",
           (int)(sizeof(table) / sizeof(table[0])));
    printf("结论：系统调用不是「内核里随便跳」，而是「按号索引的受控入口」——\n");
    printf("      这才保证了用户态只能请求被允许的服务，而不能跳到内核任意地址。\n");
    return 0;
}
